import { useBooking } from '../contexts/BookingContext';

const BlogPost: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { openBooking } = useBooking();

  const post = BLOG_POSTS.find(p => p.id === id);

  useEffect(() => {
    if (!post) {
      // Could redirect to 404, but for now redirect to blog listing
      // navigate('/blog'); 
    }
  }, [post, navigate]);

  if (!post) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <div className="text-center">
          <h2 className="text-2xl font-bold text-slate-900 mb-2">Article Not Found</h2>
          <Link to="/blog">
            <Button variant="primary">Return to Blog</Button>
          </Link>
        </div>
      </div>
    );
  }

  const relatedPosts = BLOG_POSTS.filter(p => p.id !== post.id && p.category === post.category).slice(0, 2);

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: post.title,
        text: post.excerpt,
        url: window.location.href,
      }).catch(console.error);
    } else {
      // Fallback: Copy to clipboard
      navigator.clipboard.writeText(window.location.href);
      alert('Link copied to clipboard!');
    }
  };

  return (
    <div className="bg-white min-h-screen pb-20">
      <SEO 
        title={`${post.title} | National Diagnostic Blog`}
        description={post.excerpt}
        keywords={post.tags.join(', ')}
        schema={{
          "@context": "https://schema.org",
          "@type": "BlogPosting",
          "headline": post.title,
          "image": post.imageUrl,
          "author": {
            "@type": "Person",
            "name": post.author
          },
          "publisher": {
            "@type": "Organization",
            "name": "National Diagnostic Center",
            "logo": {
              "@type": "ImageObject",
              "url": "https://res.cloudinary.com/doehytakj/image/upload/v1769064681/WhatsApp_Image_2026-01-22_at_11.07.34_AM_zrckhq.jpg"
