             <span className="px-3 py-1 bg-slate-100 text-slate-600 rounded-full text-xs font-medium flex items-center gap-1">
               <Clock size={12} /> {post.readTime}
             </span>
          </div>

          <h1 className="text-2xl sm:text-4xl md:text-5xl font-bold text-slate-900 mb-6 leading-tight">
            {post.title}
          </h1>

          <div className="flex items-center justify-between border-y border-slate-100 py-4">
            <div className="flex items-center gap-3">
