          </div>
        </header>

        {/* Featured Image */}
        <div className="mb-8 sm:mb-12 rounded-2xl overflow-hidden shadow-lg h-[250px] sm:h-[400px]">
           <LazyImage 
             src={post.imageUrl}
             alt={post.title}
             className="w-full h-full"
             imgClassName="w-full h-full object-cover"
